  "checkpoints": [
    {
      "id": 1,
      "title": "Renderer Foundation + Title Skeleton (tracer bullet)",
      "goal": "Stand up a new apps/scene-engine/ Vite app that loads a hardcoded scenes/title/scene.json (one media bg layer + one effect overlay layer) and renders it onto a 1440x1080 stage in the browser. End-to-end pipe with two layer types only — no registry, no editor, no glyph-group yet.",
      "prerequisites": [],
      "status": "pending",
      "testing_strategy": "Manual: run dev server, open browser at /, see test-fire-2.mp4 looping fullscreen with CRT scanlines/vignette overlay on top. Confirm stage dimensions render at 1440x1080 (with appropriate scaling/letterboxing). scene.json edits to opacity/blend on either layer reflect after reload. Visual smoke test only — no automated tests this checkpoint.",
      "task_groups": [
        {
          "id": 1,
          "title": "Scaffold scene-engine + migrate minimal assets",
          "objective": "Create the new apps/scene-engine/ Vite project shell and copy in the two assets the tracer-bullet title scene needs (bg video + CRT effect CSS). No renderer yet — just the empty app and its asset deps.",
          "status": "pending",
          "task_seeds": [
            { "title": "Scaffold scene-engine Vite project shell", "intent": "Stand up apps/scene-engine/ as a sibling to apps/frontend/ with package.json, vite.config.js, index.html (stage container), base stage CSS, and an empty main.js entry. Pattern after apps/frontend/ but with a single entry (multi-page comes in CP6).", "processed": true, "task_id": 1 },
            { "title": "Migrate bg video + CRT effect CSS into scene-engine", "intent": "Copy test-fire-2.mp4 from apps/font-creation/generation/melee-3/inputs/extras/ into apps/scene-engine/public/media/. Extract the .crt rules from apps/frontend/src/styles/effects.css (lines 38-61) into a standalone apps/scene-engine/src/effects/crt-overlay.css that the css-effect renderer can attach.", "processed": true, "task_id": 2 }
          ],
          "tasks": [
            {
              "id": 1,
              "title": "Scaffold scene-engine Vite project shell",
              "description": "Create the apps/scene-engine/ directory and populate it with the minimal Vite project files: package.json (vite ^8 dev dep, dev/build/preview scripts), vite.config.js (single-page root config — multi-page rollup inputs deferred to CP6), index.html with a #stage-wrap > #stage container and a module script tag pointing at /src/main.js, src/styles/stage.css that sizes #stage to exactly 1440x1080 and centers it inside #stage-wrap with appropriate scaling for smaller viewports, and src/main.js as an empty entry stub that imports the stage CSS. No renderer logic in this task — that's task 1.2.1. After this task the dev server should boot and show a black 1440x1080 stage with no errors.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": "apps/frontend/package.json", "lines": "1-26", "purpose": "Mirror Vite version (^8.0.10), script naming, and project metadata style" },
                  { "file": "apps/frontend/vite.config.js", "lines": "1-21", "purpose": "Pattern for vite.config — but use single-entry root config; do NOT replicate the multi-page rollupOptions.input map (multi-page lands in CP6)" },
                  { "file": "apps/frontend/index.html", "lines": "1-22", "purpose": "Pattern for index.html head (charset, viewport, fonts) — but drop the __bundler_thumbnail template and the home.js entry" },
                  { "file": "apps/frontend/src/shared/layout.js", "lines": "9-25", "purpose": "Reference for the #stage-wrap > #stage DOM shape used by the existing frontend; the new app uses the same outer wrapper but renders into #stage from scene.json instead of from initLayout()" }
                ],
                "related_files": [
                  "apps/frontend/src/styles/base.css"
                ]
              },
              "depends_on": [],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/", "status": "new", "description": "Directory does not yet exist" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/package.json", "status": "new", "description": "name=scene-engine, vite ^8 devDep, scripts dev/build/preview" },
                    { "path": "apps/scene-engine/vite.config.js", "status": "new", "description": "Single-entry Vite config rooted at the app dir, publicDir=public, build outDir=dist" },
                    { "path": "apps/scene-engine/index.html", "status": "new", "description": "HTML5 doc with #stage-wrap > #stage container and <script type=module src=/src/main.js>" },
                    { "path": "apps/scene-engine/src/main.js", "status": "new", "description": "Entry stub: imports stage CSS only, no other logic yet" },
                    { "path": "apps/scene-engine/src/styles/stage.css", "status": "new", "description": "Stage sizing: #stage 1440x1080 centered, with viewport-fit transform-scale for smaller screens, #stage-wrap full-viewport black bg" },
                    { "path": "apps/scene-engine/public/.gitkeep", "status": "new", "description": "Ensures public/ is tracked even before media migrates in" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "CREATE FILE apps/scene-engine/package.json", "file": "apps/scene-engine/package.json", "status": "pending" },
                { "id": 2, "command": "ADD package metadata: name='scene-engine', version='1.0.0', private=true, type='module', scripts.dev='vite', scripts.build='vite build', scripts.preview='vite preview', devDependencies.vite='^8.0.10' (MIRROR apps/frontend/package.json scripts and vite version)", "file": "apps/scene-engine/package.json", "status": "pending" },
                { "id": 3, "command": "CREATE FILE apps/scene-engine/vite.config.js", "file": "apps/scene-engine/vite.config.js", "status": "pending" },
                { "id": 4, "command": "ADD defineConfig export with root='.', publicDir='public', build.outDir='dist'. DO NOT ADD multi-page rollupOptions.input — single-entry only this checkpoint", "file": "apps/scene-engine/vite.config.js", "status": "pending" },
                { "id": 5, "command": "CREATE FILE apps/scene-engine/index.html", "file": "apps/scene-engine/index.html", "status": "pending" },
                { "id": 6, "command": "ADD HTML5 doctype, <html lang=en>, <head> with charset+viewport+<title>CODECAINE — Scene Engine</title>, body containing <div id='stage-wrap'><div id='stage'></div></div>, APPEND <script type='module' src='/src/main.js'> before </body>", "file": "apps/scene-engine/index.html", "status": "pending" },
                { "id": 7, "command": "CREATE FILE apps/scene-engine/src/main.js", "file": "apps/scene-engine/src/main.js", "status": "pending" },
                { "id": 8, "command": "ADD import './styles/stage.css' — no other logic yet (renderer wires in task 1.2.2)", "file": "apps/scene-engine/src/main.js", "status": "pending" },
                { "id": 9, "command": "CREATE FILE apps/scene-engine/src/styles/stage.css", "file": "apps/scene-engine/src/styles/stage.css", "status": "pending" },
                { "id": 10, "command": "ADD CSS rules: html,body { margin:0; height:100%; background:#000; overflow:hidden } ; #stage-wrap { position:fixed; inset:0; display:grid; place-items:center } ; #stage { position:relative; width:1440px; height:1080px; background:#000; overflow:hidden; transform-origin:center center } ; ADD media query for max-width<1440px or max-height<1080px USING transform:scale(min(100vw/1440, 100vh/1080)) via JS-set CSS var or pure CSS clamp — pick the simpler pure-CSS approach", "file": "apps/scene-engine/src/styles/stage.css", "status": "pending" },
                { "id": 11, "command": "CREATE FILE apps/scene-engine/public/.gitkeep", "file": "apps/scene-engine/public/.gitkeep", "status": "pending" }
              ]
            },
            {
              "id": 2,
              "title": "Migrate bg video + CRT effect CSS into scene-engine",
              "description": "Copy the bg video and extract the CRT-only CSS rules so the title scene's two layers have real assets to point at. Copy apps/font-creation/generation/melee-3/inputs/extras/test-fire-2.mp4 to apps/scene-engine/public/media/test-fire-2.mp4 (Vite serves /media/test-fire-2.mp4 at runtime from publicDir). Extract ONLY the .crt + .crt .scan + .crt .vign + .crt .rgb + .crt.off rules from apps/frontend/src/styles/effects.css (lines 38-61) into apps/scene-engine/src/effects/crt-overlay.css — leave the .vortex rules behind (vortex is not used by the tracer scene; vortex migration is a CP3+ concern). Do not modify apps/frontend/ — the migration is additive at this checkpoint; the eventual delete of apps/frontend/ happens in CP6.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": "apps/frontend/src/styles/effects.css", "lines": "38-61", "purpose": "Source CRT rules to extract verbatim — .crt block, .crt .scan, .crt .vign, .crt .rgb, .crt.off" }
                ],
                "related_files": [
                  "apps/font-creation/generation/melee-3/inputs/extras/test-fire-2.mp4",
                  "apps/frontend/src/shared/layout.js"
                ]
              },
              "depends_on": [1],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/font-creation/generation/melee-3/inputs/extras/test-fire-2.mp4", "status": "exists", "description": "MP4 source file (~ISO Media MP4) — origin of the bg video" },
                    { "path": "apps/frontend/src/styles/effects.css", "status": "exists", "description": "Mixed effects sheet — vortex rules at top (1-37), CRT rules in middle (38-61). Only the CRT block is needed here." },
                    { "path": "apps/scene-engine/", "status": "exists", "description": "Empty Vite shell from task 1.1.1" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/public/media/test-fire-2.mp4", "status": "new", "description": "Verbatim copy of test-fire-2.mp4 — served at /media/test-fire-2.mp4 by Vite" },
                    { "path": "apps/scene-engine/src/effects/crt-overlay.css", "status": "new", "description": "Extracted .crt rule family from effects.css lines 38-61, no other rules" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "CREATE FILE apps/scene-engine/public/media/test-fire-2.mp4 by copying apps/font-creation/generation/melee-3/inputs/extras/test-fire-2.mp4 verbatim (binary copy via cp; do not re-encode)", "file": "apps/scene-engine/public/media/test-fire-2.mp4", "status": "pending" },
                { "id": 2, "command": "CREATE FILE apps/scene-engine/src/effects/crt-overlay.css", "file": "apps/scene-engine/src/effects/crt-overlay.css", "status": "pending" },
                { "id": 3, "command": "ADD CRT rules EXTRACTed from apps/frontend/src/styles/effects.css lines 38-61: .crt {...}, .crt .scan {...}, .crt .vign {...}, .crt .rgb {...}, .crt.off {...} — verbatim ruleset, no edits to selectors or properties. DO NOT ADD .vortex, .ring, .haze rules (those live above and are not part of CRT).", "file": "apps/scene-engine/src/effects/crt-overlay.css", "status": "pending" }
              ]
            }
          ]
        },
        {
          "id": 2,
          "title": "Scene renderer + title scene",
          "objective": "Implement the minimal scene renderer that reads scene.json and dispatches layers to per-type renderers (media, css-effect). Author the hardcoded scenes/title/scene.json that exercises both renderers. Wire main.js bootstrap so opening the dev server visibly renders the scene end-to-end.",
          "status": "pending",
          "task_seeds": [
            { "title": "Implement scene-renderer + media + css-effect renderers", "intent": "Build the scene-renderer module that takes a parsed scene.json + a root DOM node, iterates layers in array order (last on top via z-index), and dispatches each layer to a per-type renderer. Implement two type renderers: media (mounts a <video> autoplay/loop/muted with fit/blend/opacity from layer.properties) and css-effect (injects the effect's stylesheet and creates the matching DOM nodes). Provide a small dispatch table indexed by layer.type so adding glyph-group later (CP2) is a one-line registration.", "processed": true, "task_id": 3 },
            { "title": "Author title scene.json + wire main.js bootstrap", "intent": "Create scenes/title/scene.json conforming to the canonical scene format from spec.md (id=title, name='Title Screen', stage 1440x1080, layers=[bg-video as media→/media/test-fire-2.mp4, crt as effect→/src/effects/crt-overlay.css]). Wire src/main.js to fetch the scene, parse, and call renderScene(scene, document.getElementById('stage')) on DOMContentLoaded. After this task the dev server should show: looping bg video at the stage, CRT scanline+vignette overlay on top.", "processed": true, "task_id": 4 }
          ],
          "tasks": [
            {
              "id": 3,
              "title": "Implement scene-renderer + media + css-effect renderers",
              "description": "Create the renderer core. apps/scene-engine/src/renderer/scene-renderer.js exports renderScene(scene, root) that: clears root, sets root size from scene.stage.{width,height}, iterates scene.layers, and for each layer calls the registered renderer for layer.type; each layer renderer returns a DOM element which renderScene appends to root in array order (later = higher z by virtue of DOM order, all positioned absolute inset:0 from a base layer style). apps/scene-engine/src/renderer/asset-renderers/index.js exports a Map type→renderer. apps/scene-engine/src/renderer/asset-renderers/media.js exports renderMedia(layer) that builds a <video> element with src=layer.asset, autoplay, muted, loop, playsinline; applies object-fit from layer.properties.fit (default 'cover'), mix-blend-mode from layer.properties.blend (default 'normal'), opacity from layer.properties.opacity (default 1). apps/scene-engine/src/renderer/asset-renderers/css-effect.js exports renderCssEffect(layer): it dynamically imports/links the layer.asset stylesheet (use a <link rel=stylesheet> appended once per unique asset to <head>, deduped) and constructs the effect's DOM. For the CRT effect specifically, build the <div class='crt'><div class='scan'></div><div class='rgb'></div><div class='vign'></div></div> structure (mirroring apps/frontend/src/shared/layout.js). Apply layer.properties.opacity if present. Return the root effect element. No tests yet — this is the rendering plumbing CP1 needs.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": "apps/frontend/src/shared/layout.js", "lines": "9-40", "purpose": "Reference DOM structure for the .crt overlay (.crt > .scan + .rgb + .vign) so css-effect renderer produces matching markup that the migrated CSS targets" },
                  { "file": ".spectre/sessions/2026-04-29_frontend-scene-system_aesqad/spec.md", "lines": "246-302", "purpose": "Canonical scene format reference — confirms layer fields used by the renderers (id, type, asset, properties.{fit,blend,opacity})" }
                ],
                "related_files": [
                  "apps/scene-engine/src/effects/crt-overlay.css",
                  "apps/scene-engine/public/media/test-fire-2.mp4"
                ]
              },
              "depends_on": [2],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/", "status": "new", "description": "Directory does not exist yet" },
                    { "path": "apps/scene-engine/src/main.js", "status": "exists", "description": "Empty entry stub from task 1.1.1, imports stage.css only" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "new", "description": "Exports renderScene(scene, root) — orchestrates per-layer rendering and DOM mounting in array z-order" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "new", "description": "Type→renderer dispatch map; exports getRenderer(type) and registerRenderer(type, fn)" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "new", "description": "renderMedia(layer) → autoplay/muted/loop <video> with fit/blend/opacity" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "status": "new", "description": "renderCssEffect(layer) → injects stylesheet (deduped) + builds .crt > .scan/.rgb/.vign DOM, returns root" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "CREATE FILE apps/scene-engine/src/renderer/scene-renderer.js", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 2, "command": "ADD FUNCTION renderScene(scene, root): clear root.innerHTML, set root.style.width=scene.stage.width+'px' and height=scene.stage.height+'px', iterate scene.layers, for each layer call getRenderer(layer.type)(layer) and append returned element to root with style.position='absolute' and style.inset='0' (z-order via DOM order)", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 3, "command": "ADD import { getRenderer } from './asset-renderers/index.js' AT TOP of scene-renderer.js", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 4, "command": "EXPORT renderScene as named export", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 5, "command": "CREATE FILE apps/scene-engine/src/renderer/asset-renderers/index.js", "file": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "pending" },
                { "id": 6, "command": "ADD VAR registry = new Map(); ADD FUNCTION registerRenderer(type, fn) that sets registry.set(type, fn); ADD FUNCTION getRenderer(type) that returns registry.get(type) or throws Error(`No renderer registered for type: ${type}`)", "file": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "pending" },
                { "id": 7, "command": "ADD import { renderMedia } from './media.js' and import { renderCssEffect } from './css-effect.js' AT TOP, then APPEND side-effect calls registerRenderer('media', renderMedia) and registerRenderer('effect', renderCssEffect) at module bottom", "file": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "pending" },
                { "id": 8, "command": "EXPORT registerRenderer, getRenderer as named exports", "file": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "pending" },
                { "id": 9, "command": "CREATE FILE apps/scene-engine/src/renderer/asset-renderers/media.js", "file": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "pending" },
                { "id": 10, "command": "ADD FUNCTION renderMedia(layer): create <video> element with src=layer.asset, autoplay=true, muted=true, loop=true, playsInline=true; ADD style.objectFit = layer.properties?.fit ?? 'cover'; ADD style.mixBlendMode = layer.properties?.blend ?? 'normal'; ADD style.opacity = layer.properties?.opacity ?? 1; ADD style.width='100%' and style.height='100%'; RETURN the video element", "file": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "pending" },
                { "id": 11, "command": "EXPORT renderMedia as named export", "file": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "pending" },
                { "id": 12, "command": "CREATE FILE apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "file": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "status": "pending" },
                { "id": 13, "command": "ADD VAR loadedStylesheets = new Set() at module scope to dedupe CSS injection", "file": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "status": "pending" },
