  "task_groups": [
    {
      "id": 1,
      "title": "Migrate assets into assets/ tree + author registry.json",
      "objective": "Relocate the bg video and CRT effect from CP1 into the spec-defined assets/ tree, copy the CODECAINE layered SVG into assets/glyphs/, and author assets/registry.json cataloguing all three by id+type+path. No renderer changes yet — this group only moves files and creates the catalogue.",
      "status": "pending",
      "task_seeds": [
        { "title": "Migrate CP1 assets and CODECAINE SVG into apps/scene-engine/assets/", "intent": "Move test-fire-2.mp4 from public/media/ to assets/media/, move src/effects/crt-overlay.css to assets/effects/crt-overlay.css, and copy the CODECAINE.css-layers.svg from the font-creation outputs into assets/glyphs/. Delete the now-empty CP1 locations (public/media/, src/effects/) so there's one canonical home per asset.", "processed": false, "task_id": null },
        { "title": "Author assets/registry.json catalogue", "intent": "Create assets/registry.json — a flat object keyed by asset id, each entry having { type, path } where path is the URL-style path Vite serves at runtime. Three entries on day one: bg-video (media → /assets/media/test-fire-2.mp4), crt-overlay (effect → /assets/effects/crt-overlay.css), codecaine-logo (glyph-group → /assets/glyphs/CODECAINE.css-layers.svg).", "processed": false, "task_id": null }
      ],
      "tasks": []
    },
    {
      "id": 2,
      "title": "Registry loader + resolve layer.asset through registry",
      "objective": "Wire the registry into the runtime: a loader module that fetches registry.json once at boot and exposes resolveAsset(id), then update scene-renderer + the existing media/css-effect renderers to look up layer.asset (now an id) through the registry instead of treating it as a literal path. Unknown ids must warn clearly and skip the layer rather than crash.",
      "status": "pending",
      "task_seeds": [
        { "title": "Create registry loader module", "intent": "apps/scene-engine/src/renderer/asset-registry.js — exports loadRegistry(url) that fetches and caches the catalogue, plus resolveAsset(id) that returns the entry { type, path } or null with a console.warn. Singleton cache keyed by url; second call returns cached registry.", "processed": false, "task_id": null },
        { "title": "Wire registry resolution into scene-renderer + media + css-effect", "intent": "Update renderScene() to await registry load before iterating layers. Update renderMedia and renderCssEffect to accept the resolved asset path (or full entry) instead of a raw path string — the simplest cut is for renderScene to resolve layer.asset → path before calling the per-type renderer, passing both the layer and the resolved path. Layers whose asset id is not in the registry are skipped with a warning.", "processed": false, "task_id": null }
      ],
      "tasks": []
    },
    {
      "id": 3,
      "title": "Glyph-group renderer + title scene with CODECAINE",
      "objective": "Implement the third asset-type renderer (glyph-group) that fetches a *.css-layers.svg and inlines it into the DOM with all named sub-layers visible. Add a small positioning helper for the spec's position {x,y} format ('center', '33%', numeric px). Update scenes/title/scene.json to use registry asset ids and to include the CODECAINE logo between bg-video and crt.",
      "status": "pending",
      "task_seeds": [
        { "title": "Implement glyph-group renderer + position helper", "intent": "apps/scene-engine/src/renderer/asset-renderers/glyph-group.js — renderGlyphGroup(layer, assetPath) fetches the SVG text, parses it with DOMParser, returns the <svg> element wrapped in a positioned <div>. apps/scene-engine/src/renderer/positioning.js — applyPosition(el, position, stage) translates {x,y} (with 'center', '%', numeric) into CSS left/top/transform. glyph-group.js uses applyPosition. Register the renderer in asset-renderers/index.js.", "processed": false, "task_id": null },
        { "title": "Update title scene.json to use registry ids + add CODECAINE layer", "intent": "Rewrite scenes/title/scene.json so layer.asset values are registry ids (bg-video, crt-overlay) and insert a new layer { id: 'codecaine-logo', type: 'glyph-group', asset: 'codecaine-logo', position: { x: 'center', y: '33%' }, properties: { scale: 0.18 } } between bg-video and crt. Scale chosen because the source SVG viewBox is 6923×1080 and the stage is 1440 wide; ~0.18 fits the word horizontally with margin. Verify end-to-end: bg video plays, chrome CODECAINE renders centered top-third, CRT overlay on top.", "processed": false, "task_id": null }
      ],
      "tasks": []
    }
  ]
},

